import { test, expect } from '@playwright/test';

test.describe('Product Detail Page Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
  });

  test('should navigate to product detail page and return to catalogue', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Verify login success
    await expect(page.getByRole('heading', { name: /products/i })).toBeVisible();

    // Click on the first product name to navigate to detail page
    const firstProductName = page.getByRole('link', { name: /sauce-labs red v3/i });
    await firstProductName.click();

    // Verify navigation to product detail page
    await expect(page).toHaveURL(/inventory-item/);
    await expect(page.getByRole('heading', { name: /sauce-labs red v3/i })).toBeVisible();

    // Click back button to return to catalogue
    const backButton = page.getByRole('button', { name: /back to products/i });
    await backButton.click();

    // Verify return to catalogue page
    await expect(page).toHaveURL(/inventory/);
    await expect(page.getByRole('heading', { name: /products/i })).toBeVisible();
  });

  test('should handle navigation when product detail page is not found', async ({ page }) => {
    // Login with standard user
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');
    const loginButton = page.getByRole('button', { name: /login/i });

    await usernameInput.fill('standard_user');
    await passwordInput.fill('secret_sauce');
    await loginButton.click();

    // Click on a product name
    const firstProductName = page.getByRole('link', { name: /sauce-labs red v3/i });
    await firstProductName.click();

    // Verify navigation to product detail page
    await expect(page).toHaveURL(/inventory-item/);

    // Attempt to click back button
    const backButton = page.getByRole('button', { name: /back to products/i });
    await backButton.click();

    // Verify return to catalogue page
    await expect(page).toHaveURL(/inventory/);
    await expect(page.getByRole('heading', { name: /products/i })).toBeVisible();
  });
});
